namespace BF4Launcher;
public static class SelfTests {
 public static string Run(){var root=Path.Combine(Path.GetTempPath(),"BF4Launcher-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"engine"));var passed=new List<string>();
 void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);passed.Add(name);}
 File.WriteAllText(Path.Combine(root,"engine/server-fields.json"),"[{\"id\":\"respawn\",\"label\":\"重生倍率\",\"type\":\"number\",\"min\":1,\"max\":300,\"defaultValue\":100}]");var r=new Repository(root);r.Load();
 string Package(string version,int value){var p=Path.Combine(root,version+".zip");using var z=ZipFile.Open(p,ZipArchiveMode.Create);var e=z.CreateEntry("mod.json");using var w=new StreamWriter(e.Open());w.Write(JsonSerializer.Serialize(new ModManifest{Id="test-mod",Name="测试模组",Version=version,Side="server",Fields=new(){new FieldDef{Id="amount",Label="倍率",Type="number",Min=1,Max=300,DefaultValue=JsonValue.Create(value)}},Operations=new(){new Operation{Field="respawn",Value=JsonValue.Create("$amount")}}},Repository.Json));return p;}
 var a=r.Import(Package("1.0",10));var b=r.Import(Package("1.1",1));Check(r.Config.Mods.Count==2,"versions-coexist");Check(!a.Enabled&&!b.Enabled,"import-disabled");r.SetModEnabled(a.Manifest.Id,true);r.SelectModVersion(a.Manifest.Id,b.Version);Check(r.Plan().Values["respawn"]!.GetValue<int>()==1,"selected-version-applies");r.SelectModVersion(a.Manifest.Id,a.Version);Check(r.Plan().Values["respawn"]!.GetValue<int>()==10,"version-selection-changes-result");Check(r.Plan().Owners["respawn"]=="测试模组 1.0","override-owner");a.Config["amount"]=JsonValue.Create(20);Check(b.Config["amount"]!.GetValue<int>()==1,"independent-version-settings");r.Save();var reloaded=new Repository(root);reloaded.Load();Check(reloaded.ModCards[0].Version=="1.0","version-selection-persists");Check(reloaded.Config.Mods.Single(m=>m.Version=="1.0").Config["amount"]!.GetValue<int>()==20,"config-persists");
 var bad=Path.Combine(root,"bad.zip");using(var z=ZipFile.Open(bad,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("../escape.txt").Open());w.Write("x");}bool blocked=false;try{r.Import(bad);}catch{blocked=true;}Check(blocked&&!File.Exists(Path.Combine(Directory.GetParent(root)!.FullName,"escape.txt")),"zip-path-validation");
 bool invalid=false;try{Repository.Validate(new(){["respawn"]=JsonValue.Create(0)},r.Fields);}catch{invalid=true;}Check(invalid,"field-range-validation");a.Manifest.Dependencies.Add("missing");bool dep=false;try{r.Plan();}catch{dep=true;}Check(dep,"dependency-check");a.Manifest.Dependencies.Clear();r.Remove(a);Check(r.Config.Mods.Count==1&&Directory.GetDirectories(Path.Combine(root,"data/removed-mods")).Length==1,"remove-preserves-config");Check(File.Exists(Path.Combine(root,"data/config.previous.json")),"config-backup");
 var migrationRoot=Path.Combine(root,"migration");Directory.CreateDirectory(Path.Combine(migrationRoot,"engine"));File.Copy(Path.Combine(root,"engine/server-fields.json"),Path.Combine(migrationRoot,"engine/server-fields.json"));
 var preset=new ModItem{Key="quick-respawn@1.1.0",Enabled=true,Directory="mods/quick-respawn/1.1.0",Manifest=new ModManifest{Id="quick-respawn",Name="快速复活",Author="本地模组库",Adapter="config",Version="1.1.0",Operations=new(){new Operation{Field="respawn",Value=JsonValue.Create("$percent")}}},Config=new(){["percent"]=JsonValue.Create(17)}};
 var kept=new ModItem{Key="custom@1",Enabled=true,Directory="mods/custom/1",Manifest=new ModManifest{Id="custom",Name="其他模组",Author="用户",Adapter="player-effects",Kind="runtime",Version="1"},Config=new(){["noSpread"]=JsonValue.Create(true)}};
 Directory.CreateDirectory(Path.Combine(migrationRoot,kept.Directory));Repository.Atomic(Path.Combine(migrationRoot,kept.Directory,"mod.json"),JsonSerializer.Serialize(kept.Manifest,Repository.Json));
 var oldConfig=new LauncherConfig{Server=new(){["respawn"]=JsonValue.Create(100)}};oldConfig.Mods.Add(preset);oldConfig.Mods.Add(kept);Directory.CreateDirectory(Path.Combine(migrationRoot,preset.Directory));File.WriteAllText(Path.Combine(migrationRoot,preset.Directory,"mod.json"),"{}");Repository.Atomic(Path.Combine(migrationRoot,"config.json"),JsonSerializer.Serialize(oldConfig,Repository.Json));
 var migrated=new Repository(migrationRoot);migrated.Load();Check(migrated.Config.Mods.Count==1&&migrated.Config.Mods[0].Key=="custom@1","redundant-preset-removed");Check(migrated.Config.Server["respawn"]!.GetValue<int>()==17,"enabled-preset-value-moved-to-base");Check(migrated.Config.Mods[0].Enabled,"other-mod-enabled-preserved");Check(migrated.Config.Mods[0].Config["noSpread"]!.GetValue<bool>(),"other-mod-config-preserved");Check(File.Exists(Path.Combine(migrationRoot,"data/migrations/config-before-presets-0.1.1.json")),"preset-migration-backup");Check(Directory.GetDirectories(Path.Combine(migrationRoot,"data/removed-mods")).Length==1,"removed-preset-files-archived");
 migrated.Config.Server["respawn"]=JsonValue.Create(42);migrated.Save();var again=new Repository(migrationRoot);again.Load();Check(again.Config.Server["respawn"]!.GetValue<int>()==42,"migration-runs-once");
 var customRoot=Path.Combine(root,"custom-same-id");Directory.CreateDirectory(Path.Combine(customRoot,"engine"));File.Copy(Path.Combine(root,"engine/server-fields.json"),Path.Combine(customRoot,"engine/server-fields.json"));preset.Manifest.Author="用户自制";oldConfig.Server["respawn"]=JsonValue.Create(100);foreach(var item in oldConfig.Mods){Directory.CreateDirectory(Path.Combine(customRoot,item.Directory));Repository.Atomic(Path.Combine(customRoot,item.Directory,"mod.json"),JsonSerializer.Serialize(item.Manifest,Repository.Json));}Repository.Atomic(Path.Combine(customRoot,"config.json"),JsonSerializer.Serialize(oldConfig,Repository.Json));var customRepo=new Repository(customRoot);customRepo.Load();Check(customRepo.Config.Mods.Count==2,"user-authored-same-id-not-removed");
 var overlayRoot=Path.Combine(root,"remaining-overlay");Directory.CreateDirectory(Path.Combine(overlayRoot,"engine"));File.Copy(Path.Combine(root,"engine/server-fields.json"),Path.Combine(overlayRoot,"engine/server-fields.json"));preset.Manifest.Author="本地模组库";kept.Manifest.Operations.Add(new Operation{Field="respawn",Value=JsonValue.Create(1)});foreach(var item in oldConfig.Mods){Directory.CreateDirectory(Path.Combine(overlayRoot,item.Directory));Repository.Atomic(Path.Combine(overlayRoot,item.Directory,"mod.json"),JsonSerializer.Serialize(item.Manifest,Repository.Json));}Repository.Atomic(Path.Combine(overlayRoot,"config.json"),JsonSerializer.Serialize(oldConfig,Repository.Json));var overlayRepo=new Repository(overlayRoot);overlayRepo.Load();Check(overlayRepo.Config.Server["respawn"]!.GetValue<int>()==100,"remaining-mod-overlay-does-not-overwrite-base");Check(overlayRepo.Plan().Values["respawn"]!.GetValue<int>()==1,"remaining-mod-overlay-preserved");

 var rotationRoot=Path.Combine(root,"rotation");Directory.CreateDirectory(Path.Combine(rotationRoot,"engine"));File.Copy(Path.Combine(root,"engine/server-fields.json"),Path.Combine(rotationRoot,"engine/server-fields.json"));File.WriteAllText(Path.Combine(rotationRoot,"engine/map-catalog.json"),"[{\"id\":\"MP_Prison\",\"label\":\"极地监狱\"},{\"id\":\"MP_Siege\",\"label\":\"上海之围\"}]");var mapPath=Path.Combine(rotationRoot,"host/runtime/GameServer/Instance/Admin/MapList.txt");Directory.CreateDirectory(Path.GetDirectoryName(mapPath)!);File.WriteAllText(mapPath,"# rotation\r\nMP_Prison ConquestLarge0 2\r\nMP_Siege ConquestLarge0 1\r\n");var rotationRepo=new Repository(rotationRoot);rotationRepo.Load();Check(rotationRepo.Config.Rotation!.Count==2,"rotation-imports-existing-managed-list");Check(rotationRepo.Config.Rotation[0].Map=="MP_Prison"&&rotationRepo.Config.Rotation[0].Rounds==2,"rotation-import-order-and-rounds");var rows=new List<RotationEntry>{new(){Map="MP_Siege",Rounds=3},new(){Map="MP_Prison",Rounds=1},new(){Map="MP_Siege",Rounds=2}};rotationRepo.SetRotation(rows);rows[0].Rounds=9;Check(rotationRepo.Config.Rotation[0].Rounds==3,"rotation-editor-does-not-alias-saved-values");var rotationAgain=new Repository(rotationRoot);rotationAgain.Load();Check(rotationAgain.Config.Rotation![0].Map=="MP_Siege"&&rotationAgain.Config.Rotation[0].Rounds==3,"rotation-persists-order-and-rounds");Check(rotationAgain.Config.Rotation.Count==3,"rotation-allows-intentional-repeats");
 bool BadRotation(List<RotationEntry> list){try{rotationRepo.ValidateRotation(list);return false;}catch{return true;}}
 Check(BadRotation(new()),"rotation-rejects-empty-list");Check(BadRotation(Enumerable.Range(0,33).Select(_=>new RotationEntry()).ToList()),"rotation-rejects-more-than-32");Check(BadRotation(new(){new(){Map="Unknown_Map"}}),"rotation-rejects-unknown-map");Check(BadRotation(new(){new(){Mode="RushLarge0"}}),"rotation-rejects-unconfigured-mode");Check(BadRotation(new(){new(){Rounds=0}})&&BadRotation(new(){new(){Rounds=11}}),"rotation-round-range");
 rotationAgain.Config.Rotation=null;rotationAgain.Save();var rotationFallback=new Repository(rotationRoot);rotationFallback.Load();Check(rotationFallback.Config.Rotation![0].Map=="MP_Siege"&&rotationFallback.Config.Rotation.Count==3,"rotation-survives-older-config-without-field");Check(File.ReadAllText(mapPath).Contains("MP_Prison ConquestLarge0 2"),"model-save-does-not-touch-managed-map-file");
var unchangedRow=new RotationEntry();int notifications=0;unchangedRow.PropertyChanged+=(sender,args)=>notifications++;unchangedRow.Map="MP_Prison";unchangedRow.Mode="ConquestLarge0";unchangedRow.Rounds=1;Check(notifications==0,"rotation-unchanged-values-do-not-mark-draft");
ClientLaunchTests.Run(Check);UiTextTests.Run(Check);
ReleaseTests.Run(root,Check);
PresetTests.Run(root,Check);
ExternalModTests.Run(root,Check);
LogCleanupTests.Run(root,Check);
GroupedModTests.Run(Check);
ExternalLibraryTests.Run(Check);
LocalModActionTests.Run(Check);
return JsonSerializer.Serialize(new{passed=passed.Count,tests=passed,sandbox=root},Repository.Json);
 }
